import java.util.List;

public final class ClaimCounter {

    public record Claim(String id, String status) {
    }

    public int countApproved(List<Claim> claims) {
        int count = 0;
        for (int index = 0; index < claims.size(); index += 1) {
            String status = claims.get(index).status();
            if (status.equals("APPROVED") || status.equals("REOPENED")) {
                count += 1;
            }
        }
        return count;
    }
}

